  ('b87684f1-cfbb-4226-b55b-31e47c6ea72e', 'c3d4e5f6-7a8b-4c33-8d23-3e4f5a6b7c43', null, 'topic'::public.curated_course_node_type, 'Foundations of U.S. Employment Law and the HR Role', 'Students begin by learning how employment law is created, enforced, interpreted, and operationalized by HR teams. The aim is not to make students act as lawyers, but to make them careful issue spotters who know when to document, escalate, investigate, or redesign a practice.', 0),
  ('e2d2db96-cd06-4035-bb72-64bbc0e4b9aa', 'c3d4e5f6-7a8b-4c33-8d23-3e4f5a6b7c43', 'b87684f1-cfbb-4226-b55b-31e47c6ea72e', 'subtopic'::public.curated_course_node_type, 'Sources of employment law', 'This subtopic gives students the legal map: statutes, regulations, agency guidance, common law, constitutional limits in public employment, and judicial precedent.', 0),
