  ('9b4279a5-a0ac-48b6-83f7-1c0a6a3fbfba', 'c3d4e5f6-7a8b-4c33-8d23-3e4f5a6b7c43', '4cbf98d9-d611-47ff-85e7-7cce8854328a', 'concept'::public.curated_course_node_type, 'ethical HR practice', null, 4),
  ('46adc14b-9afd-48ae-80fc-d84d50744668', 'c3d4e5f6-7a8b-4c33-8d23-3e4f5a6b7c43', null, 'topic'::public.curated_course_node_type, 'Employment Relationship, At-Will Doctrine, Contracts, and Wrongful Discharge', 'This section explains the legal architecture of the employment relationship. Students learn why many U.S. jobs are at will, when that default changes, and how employer documents or manager conduct can create legal exposure.', 1),
  ('09db49a9-5d0e-4605-947c-35b3a06b17b9', 'c3d4e5f6-7a8b-4c33-8d23-3e4f5a6b7c43', '46adc14b-9afd-48ae-80fc-d84d50744668', 'subtopic'::public.curated_course_node_type, 'Employment-at-will and exceptions', 'Students learn the default rule and its limits so they can recognize discharge risks before decisions are made.', 0),
