  ('1f4a3308-aad6-4710-875b-21727c8aa1f1', 'c3d4e5f6-7a8b-4c33-8d23-3e4f5a6b7c43', null, 'topic'::public.curated_course_node_type, 'Equal Employment Opportunity and Protected-Class Frameworks', 'This core section builds the statute-by-statute foundation for EEO compliance. Students learn how protected classes, coverage thresholds, administrative exhaustion, and employer defenses shape HR practice.', 2),
