  ('88b9dedf-1147-480c-95ac-1db29bdf8543', 'c3d4e5f6-7a8b-4c33-8d23-3e4f5a6b7c43', 'cbc5fec6-5866-4e30-b50f-a14e14e378fd', 'subtopic'::public.curated_course_node_type, 'Harassment and hostile work environment', 'The class covers conduct, severity, pervasiveness, reporting channels, employer knowledge, and corrective action.', 1),
