  ('35b4e2df-4899-4481-98f5-083bf4157930', 'c3d4e5f6-7a8b-4c33-8d23-3e4f5a6b7c43', null, 'topic'::public.curated_course_node_type, 'Accommodation, Disability Law, Pregnancy, Religion, and Interactive Process', 'This unit teaches students how to move from compliance slogans to a disciplined accommodation process. Students practice identifying essential functions, gathering appropriate information, and balancing employee needs with operational realities.', 4),
