update public.learning_paths
set
  title = 'Employment Law',
  goal = 'Employment Law',
  summary = 'This course prepares undergraduate Human Resources students to understand and apply U.S. employment law in day-to-day HR practice. Students learn how workplace rules are created and enforced, how to spot legal issues early, how to document decisions, how to administer legally sensitive processes, and how to partner with counsel while preserving employee trust and organizational fairness.',
  data = $empljson${"slug": "employment-law", "title": "Employment Law", "description": "This course prepares undergraduate Human Resources students to understand and apply U.S. employment law in day-to-day HR practice. Students learn how workplace rules are created and enforced, how to spot legal issues early, how to document decisions, how to administer legally sensitive processes, and how to partner with counsel while preserving employee trust and organizational fairness.", "topics": [{"id": "b87684f1-cfbb-4226-b55b-31e47c6ea72e", "type": "topic", "title": "Foundations of U.S. Employment Law and the HR Role", "description": "Students begin by learning how employment law is created, enforced, interpreted, and operationalized by HR teams. The aim is not to make students act as lawyers, but to make them careful issue spotters who know when to document, escalate, investigate, or redesign a practice.", "children": [{"id": "e2d2db96-cd06-4035-bb72-64bbc0e4b9aa", "type": "subtopic", "title": "Sources of employment law", "children": [{"id": "0502c11d-a6dc-4e66-be87-3dfaee8adc46", "type": "concept", "title": "federal statutes"}, {"id": "133e5921-9bbf-4bd1-a168-30fbd67ff081", "type": "concept", "title": "state and local law"}, {"id": "39ff0d59-aa8f-41d6-bcdc-9f8fbfc74cd6", "type": "concept", "title": "agency regulations"}, {"id": "9c255f57-40a5-4ca6-9a60-5766b6032a87", "type": "concept", "title": "case law"}, {"id": "a0b91fe9-1e79-4f80-abb5-96b8b1ba6806", "type": "concept", "title": "common-law claims"}], "description": "This subtopic gives students the legal map: statutes, regulations, agency guidance, common law, constitutional limits in public employment, and judicial precedent."}, {"id": "02558c82-6195-4d8f-8889-5fafe592dbbc", "type": "subtopic", "title": "Enforcement agencies and processes", "children": [{"id": "2395db79-2516-4801-8610-3252121c8b15", "type": "concept", "title": "EEOC"}, {"id": "7f54d4de-ec74-4639-ae69-d0518cc118f7", "type": "concept", "title": "DOL/WHD"}, {"id": "8f0ca690-06dc-4fbe-9d10-f533184ca0dc", "type": "concept", "title": "OSHA"}, {"id": "d43a7ffd-3d38-4902-ae60-f24d6944302f", "type": "concept", "title": "NLRB"}, {"id": "b02a98a5-1edf-44a3-b439-a037214869cc", "type": "concept", "title": "state civil rights and labor agencies"}], "description": "Students learn where claims go and how agencies shape employer obligations before any lawsuit is filed."}, {"id": "4cbf98d9-d611-47ff-85e7-7cce8854328a", "type": "subtopic", "title": "HR, counsel, ethics, and risk spotting", "children": [{"id": "59ea9672-ca70-47f2-943e-c85505d005bd", "type": "concept", "title": "legal advice boundaries"}, {"id": "ff3ff5c0-8c6f-4814-9dd1-07b15f4045ab", "type": "concept", "title": "privilege awareness"}, {"id": "c332080c-6bd5-4c2e-bac2-32d09929031f", "type": "concept", "title": "confidentiality"}, {"id": "1d28d120-a048-4cca-a965-3f9b593f3a63", "type": "concept", "title": "escalation triggers"}, {"id": "9b4279a5-a0ac-48b6-83f7-1c0a6a3fbfba", "type": "concept", "title": "ethical HR practice"}], "description": "The class clarifies HR's role in prevention, documentation, confidentiality, escalation, and ethical decision-making."}]}, {"id": "46adc14b-9afd-48ae-80fc-d84d50744668", "type": "topic", "title": "Employment Relationship, At-Will Doctrine, Contracts, and Wrongful Discharge", "description": "This section explains the legal architecture of the employment relationship. Students learn why many U.S. jobs are at will, when that default changes, and how employer documents or manager conduct can create legal exposure.", "children": [{"id": "09db49a9-5d0e-4605-947c-35b3a06b17b9", "type": "subtopic", "title": "Employment-at-will and exceptions", "children": [{"id": "7a07ad86-4648-4591-a0fa-c5265919e0b4", "type": "concept", "title": "public policy exception"}, {"id": "5cbe3e29-b71b-4d66-bd6e-caebae61f7bc", "type": "concept", "title": "implied contract"}, {"id": "397f7d5b-2c8f-4446-99f0-a1c3feb30215", "type": "concept", "title": "covenant of good faith"}, {"id": "afd1339b-7be3-4a1f-96cf-0c111cd901fe", "type": "concept", "title": "statutory exceptions"}, {"id": "0fc88384-6a3a-4a09-afc7-216bec590839", "type": "concept", "title": "constructive discharge"}], "description": "Students learn the default rule and its limits so they can recognize discharge risks before decisions are made."}, {"id": "2421cb5b-2ae8-40c6-a3e0-0cd91662a50b", "type": "subtopic", "title": "Contracts, offer letters, and handbooks", "children": [{"id": "ded7c9b2-f671-4bc6-8eb3-33e021c08305", "type": "concept", "title": "offer letters"}, {"id": "16e61410-36fa-49b1-8dd0-54d69d4fe646", "type": "concept", "title": "handbook disclaimers"}, {"id": "4a13cd87-fb2a-40a3-8e04-dce7c357538d", "type": "concept", "title": "probationary periods"}, {"id": "17ca4d5c-de0b-4a63-8257-71d523bc8a46", "type": "concept", "title": "policy acknowledgments"}, {"id": "018527f0-e957-4399-8b79-49c61144961b", "type": "concept", "title": "arbitration agreements"}], "description": "This subtopic shows how ordinary HR documents can become evidence of promises, procedures, or expectations."}, {"id": "75455574-bfb3-4a67-be49-6f67251133bb", "type": "subtopic", "title": "Wrongful discharge and tort theories", "children": [{"id": "71ceeaca-2593-4185-a52a-c62ffcb8aa41", "type": "concept", "title": "retaliatory discharge"}, {"id": "8a8ae740-70a7-47c8-b09d-fb1d0eeddab4", "type": "concept", "title": "defamation"}, {"id": "c7dbaaa5-b687-40c9-b1a0-f26b94e134d2", "type": "concept", "title": "intentional infliction of emotional distress"}, {"id": "ca63c066-03c8-4a57-9fbd-311abb91c2f7", "type": "concept", "title": "fraudulent inducement"}, {"id": "ad54c42e-1329-4e34-ae09-daa8dfa08c63", "type": "concept", "title": "negligent hiring or retention"}], "description": "Students examine claims that often accompany termination decisions even when no discrimination claim is obvious."}]}, {"id": "1f4a3308-aad6-4710-875b-21727c8aa1f1", "type": "topic", "title": "Equal Employment Opportunity and Protected-Class Frameworks", "description": "This core section builds the statute-by-statute foundation for EEO compliance. Students learn how protected classes, coverage thresholds, administrative exhaustion, and employer defenses shape HR practice.", "children": [{"id": "09845ff6-ffb2-45aa-98e9-a962675038de", "type": "subtopic", "title": "Title VII and protected traits", "children": [{"id": "a0e86f9b-6bc7-4a46-9557-675402706c3a", "type": "concept", "title": "race and color"}, {"id": "ed5b9bee-8c65-479e-a9e0-d08a77610686", "type": "concept", "title": "sex and pregnancy"}, {"id": "4dae5ca1-b367-40c9-993d-4c3b28db310f", "type": "concept", "title": "sexual orientation and gender identity"}, {"id": "901e9334-d0a3-4915-823f-d0f32015c773", "type": "concept", "title": "religion"}, {"id": "6ee3e69a-7d9a-4386-8ef6-aa62dd133a03", "type": "concept", "title": "national origin"}], "description": "Students learn the central antidiscrimination framework used for race, color, religion, sex, and national origin claims."}, {"id": "02a3ae12-b52a-444a-83e9-efcd0b0eae76", "type": "subtopic", "title": "Age, disability, genetic information, and pregnancy protections", "children": [{"id": "dbc802a3-69af-4772-b057-9e9d60f98a2a", "type": "concept", "title": "ADEA"}, {"id": "11d51473-371a-4b76-935d-3595b32abefc", "type": "concept", "title": "ADA"}, {"id": "d181499e-8ca5-470e-83ca-270c4ff073a8", "type": "concept", "title": "GINA"}, {"id": "f66a5f54-dd5d-41de-9f86-43f53b7c4a50", "type": "concept", "title": "Pregnant Workers Fairness Act"}, {"id": "19f66b9c-33fe-43dc-8615-d75d72fe6d76", "type": "concept", "title": "state-law expansions"}], "description": "The class compares overlapping statutes so students can avoid treating all protected-class claims as identical."}, {"id": "0610d1d7-1188-426e-87d1-85e1dea821c3", "type": "subtopic", "title": "Charge process and employer response", "children": [{"id": "78239927-e6cd-4937-ac37-73aa20cda21c", "type": "concept", "title": "intake"}, {"id": "e6c6c431-b475-41fb-a84b-e291bcbdea26", "type": "concept", "title": "position statements"}, {"id": "a4fe3487-6b2d-4a70-8773-65cba92595f4", "type": "concept", "title": "mediation"}, {"id": "6c619039-5fb2-456b-96cd-f9676c99d81d", "type": "concept", "title": "right-to-sue letters"}, {"id": "f9d8664c-70b2-40e4-813a-81ddbbcdc0cb", "type": "concept", "title": "retention of evidence"}], "description": "Students learn how EEO disputes move from internal complaint to agency charge, investigation, mediation, and possible litigation."}]}, {"id": "cbc5fec6-5866-4e30-b50f-a14e14e378fd", "type": "topic", "title": "Discrimination, Harassment, Retaliation, and Workplace Investigations", "description": "This section moves from statutes to proof. Students learn how claims are analyzed, how harassment and retaliation risks develop, and how HR investigations can either reduce or increase employer liability.", "children": [{"id": "37b5267a-a31a-4148-b036-2e202898b4d4", "type": "subtopic", "title": "Disparate treatment and disparate impact", "children": [{"id": "bef798b1-d961-4ba6-ac5d-a509b02a2ec1", "type": "concept", "title": "intent evidence"}, {"id": "396d496f-b439-4a11-93d9-184bcf7dc775", "type": "concept", "title": "comparators"}, {"id": "fde2d94f-ba0d-4281-aa03-fa127014e4e0", "type": "concept", "title": "burden shifting"}, {"id": "f1590fcc-df32-4f93-8350-d12d588bc842", "type": "concept", "title": "adverse impact"}, {"id": "1cc26303-ace5-4f8d-aa89-cfc51ff4171b", "type": "concept", "title": "business necessity"}], "description": "Students learn the two major discrimination theories and why facially neutral practices still require legal review."}, {"id": "88b9dedf-1147-480c-95ac-1db29bdf8543", "type": "subtopic", "title": "Harassment and hostile work environment", "children": [{"id": "1bb5e97e-b83f-443f-98e4-7a588e62eafe", "type": "concept", "title": "quid pro quo"}, {"id": "8884c61f-9bea-4910-aaae-085dcefa72e5", "type": "concept", "title": "hostile environment"}, {"id": "410bef12-5290-4184-b593-5ba8048bb0d2", "type": "concept", "title": "supervisor liability"}, {"id": "a8b3302f-d118-4815-b7e8-f695c239dd0a", "type": "concept", "title": "bystander reporting"}, {"id": "c9b12a70-6064-4454-81cb-de9266432391", "type": "concept", "title": "anti-harassment policy design"}], "description": "The class covers conduct, severity, pervasiveness, reporting channels, employer knowledge, and corrective action."}, {"id": "bdf0649c-2e4d-4f51-a0ba-32ffbb620d25", "type": "subtopic", "title": "Retaliation and investigations", "children": [{"id": "ca6b779e-40ff-46c6-b931-4a55a80b6202", "type": "concept", "title": "protected activity"}, {"id": "02d5d946-c56d-4381-8a75-c67403ac3081", "type": "concept", "title": "adverse action"}, {"id": "c4b43efc-10f4-4c15-84dc-7180bc6f140e", "type": "concept", "title": "causation"}, {"id": "51220819-6840-4d47-85d6-5c5a3ec67562", "type": "concept", "title": "witness interviews"}, {"id": "de14dcb9-e685-456f-8a55-c60735a145e0", "type": "concept", "title": "credibility and findings"}], "description": "Students learn why retaliation is one of the most common and dangerous claim types and how to investigate complaints fairly."}]}, {"id": "35b4e2df-4899-4481-98f5-083bf4157930", "type": "topic", "title": "Accommodation, Disability Law, Pregnancy, Religion, and Interactive Process", "description": "This unit teaches students how to move from compliance slogans to a disciplined accommodation process. Students practice identifying essential functions, gathering appropriate information, and balancing employee needs with operational realities.", "children": [{"id": "c00dc9a4-9623-4649-8f91-9d3560978115", "type": "subtopic", "title": "ADA coverage and essential functions", "children": [{"id": "af0d1169-b9ab-41da-8277-4cded5e01fb1", "type": "concept", "title": "disability definition"}, {"id": "3ac1dc64-8741-4c10-b570-9bdf29657a7f", "type": "concept", "title": "qualified individual"}, {"id": "c5018097-db9f-4677-88e5-90353ca2a3f9", "type": "concept", "title": "essential functions"}, {"id": "b7a47c32-18d8-4675-9cb6-651ba5d47747", "type": "concept", "title": "job descriptions"}, {"id": "e230c936-f2b4-49f0-9c19-bfd5058f1a56", "type": "concept", "title": "direct threat"}], "description": "Students learn how disability law defines qualified individuals, limitations, essential job duties, and reasonable accommodation."}, {"id": "3fbb2acb-dbad-4b27-af86-bfa0c01d0880", "type": "subtopic", "title": "Interactive process and undue hardship", "children": [{"id": "01657b93-cc6f-4305-b47c-cf904eb1de79", "type": "concept", "title": "medical documentation"}, {"id": "4cf1e21c-1114-4b12-bfb9-8a5211e7fc17", "type": "concept", "title": "alternative accommodations"}, {"id": "61c23140-d287-488f-ab5b-ad6bcface886", "type": "concept", "title": "undue hardship"}, {"id": "8a0af125-d1c2-41c5-ae69-5e7d28aa58d8", "type": "concept", "title": "temporary accommodations"}, {"id": "6f717f02-2fbe-4257-9a7d-b42e01526e3d", "type": "concept", "title": "process documentation"}], "description": "The class emphasizes the process discipline HR needs when accommodation requests are ambiguous, urgent, or contested."}, {"id": "5334d864-192d-4771-9204-986198c3b4fd", "type": "subtopic", "title": "Pregnancy and religious accommodation", "children": [{"id": "117707b3-832e-407b-9d88-fc4c5265411c", "type": "concept", "title": "PWFA"}, {"id": "75843910-f162-4c58-b60c-ab43b86d60eb", "type": "concept", "title": "PUMP Act awareness"}, {"id": "7f4bad2f-c675-4559-ab72-18291e58756e", "type": "concept", "title": "religious observance"}, {"id": "85cd8f82-7477-40fc-8a1a-beec46bde248", "type": "concept", "title": "dress and grooming"}, {"id": "f50194a7-f061-451c-acb1-2bf0c51716a7", "type": "concept", "title": "scheduling accommodations"}], "description": "Students compare accommodation duties across disability, pregnancy, and religion rather than assuming one rule covers all requests."}]}, {"id": "01af600e-dcac-4e90-ab60-23dd1a310980", "type": "topic", "title": "Hiring, Selection, Background Checks, Immigration, and Onboarding Compliance", "description": "This section treats hiring as a legal-risk system, not just a talent activity. Students learn to design job postings, selection tools, background checks, and onboarding processes that are valid, fair, and auditable.", "children": [{"id": "8ec55b5e-c72c-4a56-9bb0-7e4234382451", "type": "subtopic", "title": "Job postings and selection validity", "children": [{"id": "3f879c24-1ca9-4c30-ada3-3e8deed7201c", "type": "concept", "title": "job analysis"}, {"id": "f0b9121c-1580-42c2-9a75-a76a6a176dea", "type": "concept", "title": "minimum qualifications"}, {"id": "a63b386e-73f5-4dec-a1fd-c87499b3a6d1", "type": "concept", "title": "structured interviews"}, {"id": "483c3e73-1896-42b8-aea8-0d1879fe6ed1", "type": "concept", "title": "selection tests"}, {"id": "b2837599-4f90-4edd-8091-92b9858d1de3", "type": "concept", "title": "adverse impact review"}], "description": "Students learn how to reduce discrimination risk by tying hiring criteria to job-related evidence."}, {"id": "6351da8a-c7f0-425d-ada7-f7422e3e26f9", "type": "subtopic", "title": "Background checks and candidate screening", "children": [{"id": "12897e8d-7bcf-4053-96d7-c34788814332", "type": "concept", "title": "FCRA"}, {"id": "3d28fb69-1962-4ece-af9d-57deb3ffcb08", "type": "concept", "title": "ban-the-box laws"}, {"id": "4de788c0-31b7-47b2-ae1e-fded6627dd55", "type": "concept", "title": "individualized assessment"}, {"id": "247e8d7f-e7c1-4091-99fb-6927f0e466fc", "type": "concept", "title": "credit history limits"}, {"id": "ef31a058-f424-40e3-8a10-a6a44702d57a", "type": "concept", "title": "reference checks"}], "description": "The class covers the legal constraints on criminal history, credit checks, references, social media, and consumer reports."}, {"id": "91669612-ffde-4a5c-86e9-ea4939239e84", "type": "subtopic", "title": "Immigration and onboarding compliance", "children": [{"id": "f1cf7015-4e7e-4516-a8c1-a234e988efa5", "type": "concept", "title": "Form I-9"}, {"id": "cafe9c5d-d418-4601-8137-fdb16deb6534", "type": "concept", "title": "E-Verify"}, {"id": "59c53c24-eb83-4239-9626-97db9ecc2743", "type": "concept", "title": "document retention"}, {"id": "8151e881-7fe7-4771-a425-2d3fc9ae9178", "type": "concept", "title": "anti-discrimination rules"}, {"id": "af205576-0126-4e0b-aedd-f2a0af6ff86b", "type": "concept", "title": "new-hire notices"}], "description": "Students learn the basics of work authorization without overstepping into discrimination or document abuse."}]}, {"id": "131c4b7f-e73a-4f90-b4af-7279c0e09f02", "type": "topic", "title": "Wage and Hour Law, Pay Equity, Classification, and Employee Status", "description": "Students learn the legal rules that govern pay practices and worker classification. The point is to help future HR professionals prevent expensive, systematic errors in overtime, exempt status, contractor use, and pay equity.", "children": [{"id": "ff5b59d9-1b6f-4b51-ba42-85573fcb2268", "type": "subtopic", "title": "FLSA foundations", "children": [{"id": "c05b744a-6dcd-45b2-90df-b1df7ec6f45c", "type": "concept", "title": "minimum wage"}, {"id": "5db14d29-754d-475b-af58-5ea2ece3964a", "type": "concept", "title": "overtime"}, {"id": "015286be-8c21-4eac-89e6-52ab431e070d", "type": "concept", "title": "hours worked"}, {"id": "faa1732c-c429-4004-b900-635cabcc17ad", "type": "concept", "title": "meal and rest periods"}, {"id": "add0a994-97ea-48ba-a306-d35a5b0912db", "type": "concept", "title": "recordkeeping"}], "description": "This subtopic covers minimum wage, overtime, hours worked, recordkeeping, and common pay-practice pitfalls."}, {"id": "eaebc3e5-d232-4069-9b0e-ec13817033fd", "type": "subtopic", "title": "Exempt status and worker classification", "children": [{"id": "750431b5-f4e8-409a-a243-123f69f062f9", "type": "concept", "title": "executive exemption"}, {"id": "14c6d460-6c25-4adf-8288-3b0be329159b", "type": "concept", "title": "administrative exemption"}, {"id": "d83af7df-3704-45a7-a67b-cbb3512d5fce", "type": "concept", "title": "professional exemption"}, {"id": "5a22ae04-2a14-4493-bbc8-13a6ffd8f245", "type": "concept", "title": "independent contractors"}, {"id": "79e856d6-d9ff-43de-997f-2ed00c039878", "type": "concept", "title": "interns and trainees"}], "description": "Students learn to classify employees and contractors through legal tests rather than job titles or budget preferences."}, {"id": "b6311793-d91f-49c1-a53d-c0c22095040a", "type": "subtopic", "title": "Pay equity and transparency", "children": [{"id": "031a8c00-3914-423c-938a-f09afa18f71a", "type": "concept", "title": "Equal Pay Act"}, {"id": "6f37f015-1eab-43e2-b3aa-7aa8e3147933", "type": "concept", "title": "Title VII pay claims"}, {"id": "a2d42553-2c30-4607-b99a-aa54e32fa5eb", "type": "concept", "title": "salary history restrictions"}, {"id": "e02c7ee5-6d43-4734-874c-8a6a67959dc4", "type": "concept", "title": "pay range posting"}, {"id": "2df7e468-e1c4-4c9e-90fe-4c5e4045762a", "type": "concept", "title": "compensation audits"}], "description": "The class connects compensation compliance to equity analysis, salary history bans, and pay transparency rules."}]}, {"id": "236b3dfa-cce5-4d22-89c1-589e086ee7fb", "type": "topic", "title": "Leave, Benefits, FMLA, ADA/FMLA/Workers' Compensation Intersections", "description": "This unit helps students manage absences and medical information without confusing overlapping laws. Students learn to coordinate job protection, benefits, accommodations, and return-to-work decisions.", "children": [{"id": "5a26a10d-d251-43c9-bb87-a4cece548067", "type": "subtopic", "title": "FMLA eligibility and administration", "children": [{"id": "1569f8fc-9bed-43d2-b2c0-359242f3b7a9", "type": "concept", "title": "12-month and hours requirements"}, {"id": "8111da85-02bb-4fa1-9077-c8e42b3b3b75", "type": "concept", "title": "serious health condition"}, {"id": "5705c9c9-6b91-45b1-adfa-0c9b615534ad", "type": "concept", "title": "intermittent leave"}, {"id": "77f486cb-07f8-4ac3-871f-d0e48ed09a26", "type": "concept", "title": "medical certification"}, {"id": "560ee307-5bbd-474e-822e-08a5ff116818", "type": "concept", "title": "job restoration"}], "description": "Students learn the mechanics of covered employers, eligible employees, qualifying reasons, notices, certification, and job restoration."}, {"id": "a8324332-76b2-458e-ac34-1164bb7138f8", "type": "subtopic", "title": "Leave as accommodation and return to work", "children": [{"id": "fea9ee17-7420-43b1-a475-e3d67f98973e", "type": "concept", "title": "extended leave"}, {"id": "bc2126b2-80e6-4015-831a-e0162ffebfbb", "type": "concept", "title": "fitness-for-duty"}, {"id": "c1561fb4-0054-430c-935d-ab38d6907d60", "type": "concept", "title": "light duty"}, {"id": "95bd7ce0-a874-4d5d-83d1-a5039d56c470", "type": "concept", "title": "reasonable accommodation"}, {"id": "5bda30b3-b125-4221-9d34-17b72f3d4bbf", "type": "concept", "title": "undue hardship"}], "description": "The class explores how ADA, FMLA, workers' compensation, and employer leave policies interact."}, {"id": "d32b0fc6-6800-4e61-8fec-f8a1bbfe0b4c", "type": "subtopic", "title": "Benefits and medical information", "children": [{"id": "b45a7e19-a218-4dd8-9fdb-e2b428b1bb6e", "type": "concept", "title": "benefit continuation"}, {"id": "6211bdcc-bc0a-4e75-b7c4-d485035a2232", "type": "concept", "title": "COBRA awareness"}, {"id": "c2cfda16-c35a-4ce0-9ce7-c56f4cd7ded3", "type": "concept", "title": "HIPAA awareness"}, {"id": "2d099288-871b-4fda-a2f4-1bf9fa0cdc04", "type": "concept", "title": "separate medical files"}, {"id": "f35b3bb0-d27d-44b6-878b-7353c1de8249", "type": "concept", "title": "confidentiality protocols"}], "description": "Students learn to protect confidentiality while administering benefits and leave-related documentation."}]}, {"id": "a4279133-f888-4267-b62b-23d536d567b8", "type": "topic", "title": "Workplace Safety, Health, Workers' Compensation, and Violence Prevention", "description": "This section frames safety as both a legal obligation and a core HR responsibility. Students learn how hazards, reporting, training, retaliation, and workers' compensation connect to employee relations.", "children": [{"id": "9675080c-b0b2-4ecf-9b7b-5316d8dd1285", "type": "subtopic", "title": "OSHA duties and hazard prevention", "children": [{"id": "ee2d8405-fa3a-4c9b-9c92-4077271b887d", "type": "concept", "title": "general duty clause"}, {"id": "933244d1-30e3-48cf-98b4-bc59c3a80191", "type": "concept", "title": "standards"}, {"id": "b00eb39e-42ef-4e58-805e-e24e8f167dab", "type": "concept", "title": "training"}, {"id": "ade414bd-93de-48f9-b605-d7a1b16771d3", "type": "concept", "title": "inspections"}, {"id": "6093ede6-00d5-4772-92d8-0485ffc4efa2", "type": "concept", "title": "hazard communication"}], "description": "Students learn the basic duty to provide a safe workplace and the compliance tools used to reduce hazards."}, {"id": "2fb5ec33-d62c-49d4-8614-b16a4fa08b1f", "type": "subtopic", "title": "Injury reporting and workers' compensation", "children": [{"id": "28e24491-ab34-4fb5-897e-0867097275da", "type": "concept", "title": "OSHA logs"}, {"id": "fb63e65e-b516-4257-ae15-54f5f5ee40c8", "type": "concept", "title": "incident investigation"}, {"id": "bfc7f243-bf26-4f77-918a-00b4955b165c", "type": "concept", "title": "workers' compensation claims"}, {"id": "e7179130-fa3a-43b3-b487-0b04ee28061c", "type": "concept", "title": "modified duty"}, {"id": "1888069e-c483-496c-b43d-612550bc8439", "type": "concept", "title": "anti-retaliation rules"}], "description": "The class covers reporting duties, recordability, claim coordination, and return-to-work issues."}, {"id": "6c4c5442-8824-4107-922e-df96f393ce2c", "type": "subtopic", "title": "Workplace violence and wellbeing", "children": [{"id": "3bbfc3bf-d418-48d1-8d81-bbbe2ca5b102", "type": "concept", "title": "threat assessment"}, {"id": "f252ea78-5b79-4f44-b5b8-2c3b4c57fe67", "type": "concept", "title": "domestic violence spillover"}, {"id": "826aa3f0-0997-4a45-ad2e-ab1d0d37bdbb", "type": "concept", "title": "de-escalation"}, {"id": "5896337f-7897-4050-b08d-e9d7156252a6", "type": "concept", "title": "emergency action plans"}, {"id": "51d0114f-405d-4246-9b63-c110cfa15cbe", "type": "concept", "title": "psychological safety"}], "description": "Students examine how HR policy, supervision, security, and culture reduce serious workplace risks."}]}, {"id": "fa3db584-27f1-42ef-8a89-b29551a70504", "type": "topic", "title": "Employee Privacy, Monitoring, Data Governance, and AI in HR", "description": "This unit makes the course current by connecting traditional privacy issues to modern HR technology. Students learn that monitoring, analytics, and AI can create legal, ethical, and employee-trust problems even when tools appear efficient.", "children": [{"id": "39c66080-38e6-4ae2-89d6-4b9f3a14a40b", "type": "subtopic", "title": "Monitoring and workplace privacy", "children": [{"id": "bfadb88c-422d-4a79-9743-884d742bf842", "type": "concept", "title": "electronic communications"}, {"id": "2886a255-4b40-4e66-8911-4c9d35f71cc5", "type": "concept", "title": "device policies"}, {"id": "904de54e-c26c-4c31-a9f7-7d34c9db484f", "type": "concept", "title": "GPS tracking"}, {"id": "df235735-c6c9-46f0-83f0-1a032720afb0", "type": "concept", "title": "social media"}, {"id": "738dd0dc-868e-4cb6-8710-937c0d607d6c", "type": "concept", "title": "off-duty conduct"}], "description": "Students learn the limits and expectations around email, devices, location tracking, cameras, social media, and off-duty conduct."}, {"id": "8b49359e-dd25-4ee5-a52a-567ebb0842de", "type": "subtopic", "title": "HR data governance", "children": [{"id": "7855135b-c92a-4e48-a8c9-fc63442d0ff2", "type": "concept", "title": "personnel records"}, {"id": "8a99d924-8914-4f68-a549-3471dad64deb", "type": "concept", "title": "medical confidentiality"}, {"id": "6997d9ac-c292-4589-86a8-b06f66e802df", "type": "concept", "title": "role-based access"}, {"id": "a1c4c128-36f6-42a7-8ed4-f19fadbe9cd4", "type": "concept", "title": "data retention"}, {"id": "a60b64d7-6b5a-45ab-8a5a-3e8b4eca6dcd", "type": "concept", "title": "breach response"}], "description": "The class covers personnel files, medical data, access controls, data minimization, breach response, and retention."}, {"id": "992838a2-680a-4614-b536-dfc607ffe4b6", "type": "subtopic", "title": "AI, biometrics, and algorithmic tools", "children": [{"id": "bc0b70a6-f366-4502-95c6-5a98b4bfa299", "type": "concept", "title": "algorithmic hiring"}, {"id": "df7b5cc9-7240-4ab9-9338-d904043e655e", "type": "concept", "title": "bias audits"}, {"id": "335ad2d4-8cc4-4388-ab5c-b8f74ef368d9", "type": "concept", "title": "biometric data"}, {"id": "2f13cb48-7607-497e-bd93-004545463976", "type": "concept", "title": "vendor contracts"}, {"id": "00080f5f-b684-4bc0-a335-fafc082e1628", "type": "concept", "title": "human oversight"}], "description": "Students learn to evaluate HR technology for bias, transparency, privacy, vendor risk, and human review."}]}, {"id": "711f7e5f-5b47-4b06-b611-94ccf80beda7", "type": "topic", "title": "Labor Relations, Union Organizing, Collective Activity, and Collective Bargaining", "description": "This section ensures HR students understand worker voice and labor law even if they work in a nonunion setting. Students learn what employers may and may not do when employees organize, bargain, complain, or act together.", "children": [{"id": "b31284be-00c1-4244-aa12-2130f568f60f", "type": "subtopic", "title": "NLRA rights and protected concerted activity", "children": [{"id": "879ecbd9-8f31-43b0-b236-c464e0fdedc0", "type": "concept", "title": "Section 7 rights"}, {"id": "ad808f3f-b975-4380-96a0-5b840359db30", "type": "concept", "title": "protected concerted activity"}, {"id": "9bd3e6f5-5fb9-4a95-b7e5-fa5680e58c3f", "type": "concept", "title": "unfair labor practices"}, {"id": "42c7ebe2-aef1-4400-8c23-3e683b29f64b", "type": "concept", "title": "social media activity"}, {"id": "e799d3ea-bb13-4468-83a6-cb34722e787e", "type": "concept", "title": "nonunion workplaces"}], "description": "Students learn that labor law protects many group workplace actions even outside formal union campaigns."}, {"id": "dc2065c2-8347-491e-b490-d0f51576bc89", "type": "subtopic", "title": "Union organizing and employer conduct", "children": [{"id": "eabc6438-98c3-4950-b0de-c4948952559b", "type": "concept", "title": "representation petitions"}, {"id": "c66d5c5f-b705-402a-bb05-bd74d125a7eb", "type": "concept", "title": "TIPS rules"}, {"id": "e19f13b0-ad3a-4c6f-89de-48491318a6a6", "type": "concept", "title": "captive audience issues"}, {"id": "301ed17f-7d4a-4518-9487-343f119bb6c5", "type": "concept", "title": "card campaigns"}, {"id": "1a89d573-accf-47fa-8bf8-30d19d60a12d", "type": "concept", "title": "election objections"}], "description": "The class teaches lawful employer communication, supervisor training, election procedures, and common organizing risks."}, {"id": "819b6719-4313-48c1-8c7b-d76ef789f72e", "type": "subtopic", "title": "Collective bargaining and contract administration", "children": [{"id": "047ef30c-9524-4967-9a6a-6955f053d6e7", "type": "concept", "title": "duty to bargain"}, {"id": "215f6461-cf36-439d-8bca-aa767e568954", "type": "concept", "title": "management rights"}, {"id": "7ae0a0b0-5ad9-41ac-81b6-d9d7d281a528", "type": "concept", "title": "just cause"}, {"id": "27e4e9a5-12eb-410f-acca-d29395009e21", "type": "concept", "title": "grievances"}, {"id": "49773f2c-efd9-4328-9fa8-4e576121f44c", "type": "concept", "title": "arbitration"}], "description": "Students learn the basics of bargaining obligations and how HR supports contract interpretation and grievance handling."}]}, {"id": "1e7370de-7ffd-4ae8-a0c4-6b7b9e3617f1", "type": "topic", "title": "Compliance Documentation, Policies, Handbooks, and Recordkeeping", "description": "This practical section teaches students how documentation functions as legal evidence, management communication, and compliance infrastructure. The goal is accurate, consistent, proportionate records that support fair decisions.", "children": [{"id": "9362eb94-a524-4d74-8294-0cbd736b2b78", "type": "subtopic", "title": "Policy and handbook drafting", "children": [{"id": "c752a86b-2968-4b73-a6f7-e9eb392b30f3", "type": "concept", "title": "disclaimers"}, {"id": "fd755ffa-e28d-4915-bb3a-59b06e602dec", "type": "concept", "title": "anti-harassment policy"}, {"id": "3d793b6b-d5f8-4f8f-aef6-f4e15355c2f2", "type": "concept", "title": "leave policy"}, {"id": "0efb126e-5ea2-42d6-9abc-02a5aa698a1d", "type": "concept", "title": "social media policy"}, {"id": "67b00dae-6aef-449c-b6b2-048bcc5ef376", "type": "concept", "title": "NLRA-sensitive language"}], "description": "Students learn how policies communicate expectations while avoiding unintended promises or unlawful restrictions."}, {"id": "82e0b68e-2fc4-4f2a-b0ea-d3b8a95a9d38", "type": "subtopic", "title": "Personnel files and retention", "children": [{"id": "42902f3c-0e46-441b-a791-e64dc53de835", "type": "concept", "title": "personnel file structure"}, {"id": "96c930c2-ff5f-4706-8d59-165f17007a5c", "type": "concept", "title": "medical file separation"}, {"id": "50730840-2500-428e-83d6-5cfda4b6e9df", "type": "concept", "title": "I-9 files"}, {"id": "f90e6a76-175d-4b17-885e-74d902c0d488", "type": "concept", "title": "retention schedules"}, {"id": "c080267c-a18e-4a55-b9a8-c2e4125ffb40", "type": "concept", "title": "litigation holds"}], "description": "The class covers what to keep, where to keep it, who can access it, and how long records should be retained."}, {"id": "3c702dab-2c4a-41d4-8963-536004dcd859", "type": "subtopic", "title": "Discipline and performance documentation", "children": [{"id": "c5a9e595-5a52-490c-952d-5820fc6d5b53", "type": "concept", "title": "contemporaneous notes"}, {"id": "2de96179-34cf-4729-919b-a15440902165", "type": "concept", "title": "objective language"}, {"id": "b4eca15e-242f-4809-a9c6-ba3362e942e6", "type": "concept", "title": "consistency"}, {"id": "833951b3-b4f3-4b54-94b2-ed065c4c6450", "type": "concept", "title": "performance improvement plans"}, {"id": "c30dee87-1b8e-4502-a34e-01e3ae9577ea", "type": "concept", "title": "final warnings"}], "description": "Students learn to document facts, expectations, coaching, progressive discipline, and employee responses."}]}, {"id": "b5b030f2-5c6f-456c-b376-9bcde150394b", "type": "topic", "title": "Employment-Law Case Briefing, Remedies, Litigation, and Risk Management", "description": "This section trains students to read legal authority and translate it into HR practice. Students learn what courts and agencies look for, what remedies are available, and how good process reduces exposure.", "children": [{"id": "cbdcf771-9d2c-4e34-b2b5-c7811ddaf279", "type": "subtopic", "title": "Case briefing and legal reasoning", "children": [{"id": "a1724aeb-4f7b-41bf-a5b3-655facc7a130", "type": "concept", "title": "facts"}, {"id": "2d5f998b-5649-46bd-99d7-f02162ed4ab9", "type": "concept", "title": "procedural posture"}, {"id": "b22818db-7805-4c3a-971c-e4285050408e", "type": "concept", "title": "legal issue"}, {"id": "234b6dc5-5566-46b7-94db-5156190c4184", "type": "concept", "title": "holding"}, {"id": "28a4d980-f778-49a5-8fa6-52fc9a4748d6", "type": "concept", "title": "practice implications"}], "description": "Students learn to identify facts, issues, rules, holdings, reasoning, and practical HR lessons from cases."}, {"id": "9b4fa0ac-6d47-442f-a635-0f7209af773f", "type": "subtopic", "title": "Administrative charges, litigation, and arbitration", "children": [{"id": "5802268c-bffd-48cb-9dd7-f0bc743557da", "type": "concept", "title": "agency charge"}, {"id": "c56c8a27-2ed2-4bc3-8417-65c7f040a9fb", "type": "concept", "title": "discovery"}, {"id": "a3574eb3-8b0f-4fee-8847-5cb7e2a5bb39", "type": "concept", "title": "summary judgment"}, {"id": "e73596d3-f056-4db4-b0e5-1267b6dfadc7", "type": "concept", "title": "arbitration"}, {"id": "e4b8d6a0-d298-4e39-b6fd-620cd169e31c", "type": "concept", "title": "settlement agreements"}], "description": "The class traces the lifecycle of disputes so students understand deadlines, evidence, and resolution options."}, {"id": "9bd8207e-a262-4c6c-8460-fb10172fdb3d", "type": "subtopic", "title": "Remedies and risk management", "children": [{"id": "0916bac3-56fe-4d2d-a82a-4d62c762920d", "type": "concept", "title": "back pay"}, {"id": "de2a1bdb-2cc3-4a6c-a6a5-8064b4f03e72", "type": "concept", "title": "front pay"}, {"id": "4d37d8f8-af24-4af8-8f16-9cd9e4996d91", "type": "concept", "title": "compensatory damages"}, {"id": "e32c94f2-a891-4670-b154-9ea528110320", "type": "concept", "title": "punitive damages"}, {"id": "3cbe76b9-af38-437b-96fc-642f2b8ce89c", "type": "concept", "title": "injunctive relief"}], "description": "Students learn the consequences of violations and the prevention systems that reduce risk."}]}, {"id": "314e4ab1-9460-46fb-8812-99e86e4c4a71", "type": "topic", "title": "Multistate, Remote Work, Global, and Emerging Employment-Law Issues", "description": "The final topic prepares students for modern HR work across jurisdictions and work arrangements. Students learn to avoid assuming that one federal rule or home-state policy is enough.", "children": [{"id": "aa87ed76-b692-4a7b-9d5a-49dbde613211", "type": "subtopic", "title": "State and local law variation", "children": [{"id": "f84e98d8-18f8-45b3-a145-14886d704b8c", "type": "concept", "title": "paid sick leave"}, {"id": "85736816-dfd9-46f5-91fb-78397832cff8", "type": "concept", "title": "minimum wage"}, {"id": "7c1dd259-f2c7-47d7-ad8a-9c194cba069e", "type": "concept", "title": "pay transparency"}, {"id": "8e10c686-2adb-4e72-a0c7-a9b80acf7696", "type": "concept", "title": "noncompete limits"}, {"id": "2067c655-0a37-450a-8eb2-00cde412caca", "type": "concept", "title": "final pay rules"}], "description": "Students learn why HR must track jurisdiction-specific rules for leave, pay, privacy, hiring, and termination."}, {"id": "b24c65e3-1770-409c-90e7-fc37a5eec5a1", "type": "subtopic", "title": "Remote and hybrid work compliance", "children": [{"id": "a96d3549-8fde-4473-b19a-328cb06e61af", "type": "concept", "title": "work location approvals"}, {"id": "a3ecbb87-e139-4733-a578-fcb19e70c225", "type": "concept", "title": "state registration"}, {"id": "3f85d7a2-c736-4b77-a2c4-44e1eca2f84e", "type": "concept", "title": "expense reimbursement"}, {"id": "fbb0bdd8-19cc-4d89-ae03-2e9cea36f94d", "type": "concept", "title": "remote safety"}, {"id": "a353d52c-365f-4a9a-b0bf-efb954a19f30", "type": "concept", "title": "timekeeping"}], "description": "The class covers multistate payroll, tax coordination, workers' compensation, expense reimbursement, and policy consistency."}, {"id": "f493b87a-550b-4e38-9c23-4b3044760512", "type": "subtopic", "title": "Global and emerging worker-protection issues", "children": [{"id": "76b93ac5-ffea-4a59-a931-0c72754ebebb", "type": "concept", "title": "gig work"}, {"id": "8311036e-c070-41e4-b061-1fbb58946711", "type": "concept", "title": "platform labor"}, {"id": "01d1e5d9-a2b1-4740-b8f9-f01f6abcbadb", "type": "concept", "title": "restrictive covenants"}, {"id": "7b1cd517-f3a9-43a3-baf4-5da982c6e68d", "type": "concept", "title": "global mobility"}, {"id": "28a71169-acdb-4bdb-810b-f635f58ac594", "type": "concept", "title": "climate and heat safety"}], "description": "Students survey cross-border and future-facing topics without losing the U.S. course focus."}]}], "dbBacked": true}$empljson$::jsonb,
